 public static class Physics {public static RaycastHit[] RaycastAll(Vector3 start,Vector3 direction,float distance,int mask,QueryTriggerInteraction trigger)=>World.Support(start)?new[]{new RaycastHit{collider=new Collider(),normal=Vector3.up,point=new Vector3(start.x,0,start.z)}}:new RaycastHit[0];public static bool Raycast(Vector3 start,Vector3 direction,out RaycastHit hit,float dist,int mask,QueryTriggerInteraction trigger){var q=new Vector3(start.x,0,start.z);float h=World.Height(q);World.MinSampleZ=Math.Min(World.MinSampleZ,start.z);World.MaxSampleZ=Math.Max(World.MaxSampleZ,start.z);hit=new RaycastHit{point=new Vector3(start.x,h,start.z),normal=new Vector3(0,World.Slope,0),collider=new Collider{IsCar=World.CarUnder,IsActor=World.CharacterUnder},rigidbody=World.DynamicUnder?new Rigidbody():null};return start.y>=h&&start.y-dist<=h;}public static bool CheckBox(Vector3 centre,Vector3 half,Quaternion yaw,int mask,QueryTriggerInteraction q)=>World.Block(centre);}
}
